<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { marked } from 'marked'
import DOMPurify from 'dompurify'
import { showFailToast,showSuccessToast } from 'vant'
import { chatApi,sessionApi } from '@/api'
import type { ChatMessage,Citation } from '@/types'
import { streamChat } from '@/utils/sse'
const route=useRoute();const router=useRouter();const messages=ref<ChatMessage[]>([]);const input=ref('');const loading=ref(false);const streaming=ref(false);const scroller=ref<HTMLDivElement>();const controller=ref<AbortController|null>(null)
const sessionId=ref<number|undefined>(route.params.sessionId?Number(route.params.sessionId):undefined)
const documentId=ref<number|undefined>(route.query.document_id?Number(route.query.document_id):undefined)
const feedback=ref({show:false,rating:'LIKE',reason:'',messageId:0})
const welcome=computed(()=>messages.value.length===0)
function render(text:string){return DOMPurify.sanitize(marked.parse(text||'') as string)}
async function scrollBottom(){await nextTick();if(scroller.value)scroller.value.scrollTop=scroller.value.scrollHeight}
async function load(){if(!sessionId.value)return;loading.value=true;try{const r=await sessionApi.messages(sessionId.value);messages.value=r.data.data.messages}catch(e){showFailToast((e as Error).message)}finally{loading.value=false;scrollBottom()}}
async function send(text?:string){const question=(text??input.value).trim();if(!question||streaming.value)return;input.value='';streaming.value=true;controller.value=new AbortController();const assistant:ChatMessage={role:'ASSISTANT',content:'',status:'SUCCESS',citations:[],suggestions:[]};messages.value.push({role:'USER',content:question},assistant);scrollBottom();try{await streamChat({question,session_id:sessionId.value,document_id:documentId.value,enable_web:true,enable_db_tool:true,stream:true},event=>{if(event.event==='delta')assistant.content+=event.data.content||'';else if(event.event==='citation')assistant.citations=event.data.citations||[];else if(event.event==='suggestion')assistant.suggestions=event.data.suggestions||[];else if(event.event==='done'){assistant.message_id=event.data.message_id;assistant.status='SUCCESS';assistant.is_grounded=event.data.guard?.is_grounded;assistant.citations=event.data.citations||assistant.citations;if(!sessionId.value){sessionId.value=event.data.session_id;router.replace(`/app/chat/${event.data.session_id}`)}}else if(event.event==='error'){assistant.status='FAILED';assistant.content+=`\n\n${event.data.message||'回答生成失败'}`;showFailToast(event.data.message||'回答生成失败')};scrollBottom()},controller.value.signal)}catch(e:any){if(e.name!=='AbortError'){assistant.status='FAILED';assistant.content+='\n\n请求中断，请稍后重试。';showFailToast(e.message||'问答失败')}}finally{streaming.value=false;controller.value=null;scrollBottom()}}
function stop(){controller.value?.abort()}
function openFeedback(message:ChatMessage,rating:string){if(!message.message_id)return;feedback.value={show:true,rating,reason:'',messageId:message.message_id}}
async function submitFeedback(){try{await chatApi.feedback(feedback.value.messageId,{rating:feedback.value.rating,reason:feedback.value.reason});feedback.value.show=false;showSuccessToast('感谢你的反馈')}catch(e){showFailToast((e as Error).message)}}
function openCitation(c:Citation){if(c.source_type==='WEB'&&c.source_url)window.open(c.source_url,'_blank','noopener');else if(c.document_id)router.push(`/app/documents/${c.document_id}`)}
onMounted(load);onBeforeUnmount(()=>controller.value?.abort())
</script>
<template><div class="chat-page"><header class="chat-head"><button class="icon-btn" @click="router.push('/app/sessions')">‹</button><div><span class="eyebrow">RAG ASSISTANT</span><h2>{{sessionId?'继续咨询':'校园卡智能问答'}}</h2></div></header><div class="source-mode"><span>按问题自动选择</span><span>知识库</span><span>数据库</span><span>联网补充</span></div><div ref="scroller" class="chat-scroll"><van-loading v-if="loading" class="center-loading"/><section v-if="welcome" class="chat-welcome"><div class="ai-orb">AI</div><h2>有什么校园卡问题？</h2><p>我会先判断问题类型：文档问题查知识库，账户问题查本地数据库，混合问题同时查询；只有本地资料不足或信息要求较新时才联网补充。</p><div class="prompt-list"><button @click="send('校园卡丢失后应该怎么补办？')">校园卡丢失后应该怎么补办？</button><button @click="send('校园卡有哪些充值方式？')">校园卡有哪些充值方式？</button><button @click="send('校园卡消费范围包括哪些？')">校园卡消费范围包括哪些？</button></div></section><template v-for="(message,index) in messages" :key="message.message_id||index"><div :class="['message',message.role==='USER'?'user':'assistant']"><div v-if="message.role==='ASSISTANT'" class="avatar">AI</div><div class="bubble"><div v-if="message.content" class="markdown-body" v-html="render(message.content)"></div><div v-else class="typing"><i></i><i></i><i></i></div><template v-if="message.citations?.length"><div class="citations"><p>参考来源</p><button v-for="citation in message.citations" :key="`${citation.title}-${citation.sort_order}`" @click="openCitation(citation)"><span>{{citation.source_type==='WEB'?'网页':citation.source_type==='TOOL'?'工具':'文档'}}</span><strong>{{citation.title}}</strong><small>{{citation.snippet}}</small></button></div></template><div v-if="message.role==='ASSISTANT'&&message.status==='SUCCESS'&&message.message_id" class="message-tools"><button @click="openFeedback(message,'LIKE')">有帮助</button><button @click="openFeedback(message,'DISLIKE')">需改进</button><span v-if="message.is_grounded===false" class="guard">无依据兜底</span></div><div v-if="message.role==='ASSISTANT'&&message.suggestions?.length&&!streaming" class="suggestions"><button v-for="item in message.suggestions" :key="item" @click="send(item)">{{item}}</button></div></div></div></template></div><footer class="composer"><textarea v-model="input" rows="1" placeholder="输入问题，最多1000字" @keyup.enter.exact.prevent="send()"></textarea><button v-if="streaming" class="send-btn stop" @click="stop">停止</button><button v-else class="send-btn" :disabled="!input.trim()" @click="send()">发送</button></footer><van-dialog v-model:show="feedback.show" :title="feedback.rating==='LIKE'?'反馈有帮助':'反馈需改进'" show-cancel-button confirm-button-text="提交" @confirm="submitFeedback"><van-field v-model="feedback.reason" type="textarea" rows="3" maxlength="500" show-word-limit placeholder="可补充具体原因（选填）"/></van-dialog></div></template>
